//! Tool #6 (`osabt lexi`) — Curated offline Classical Greek, Classical Latin, and ICZN/ICNafp
//! biological & anatomical morpheme lexicon.

/// Positional role of a morpheme inside compound scientific and anatomical terms.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum MorphemeRole {
    Prefix,
    Stem,
    Suffix,
}

impl MorphemeRole {
    pub fn label(self) -> &'static str {
        match self {
            Self::Prefix => "prefix",
            Self::Stem => "root/stem",
            Self::Suffix => "suffix",
        }
    }
}

/// Classical or taxonomic source language of a morpheme.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum MorphemeOrigin {
    Greek,
    Latin,
    NeoLatinTaxonomic,
}

impl MorphemeOrigin {
    pub fn label(self) -> &'static str {
        match self {
            Self::Greek => "Greek",
            Self::Latin => "Latin",
            Self::NeoLatinTaxonomic => "ICZN/ICNafp Latin",
        }
    }
}

/// Single entry in the offline OSABT biological etymology lexicon.
#[derive(Debug, Clone)]
pub struct MorphemeEntry {
    pub canonical_id: &'static str,
    /// All lowercase surface allomorphs (without connecting vowels unless intrinsic).
    pub forms: &'static [&'static str],
    pub role: MorphemeRole,
    pub origin: MorphemeOrigin,
    /// Original Greek/Latin citation lemma (e.g. `πτερόν (pteron)` or `folius`).
    pub classical_lemma: &'static str,
    pub gloss: &'static str,
    /// Representative biological or anatomical cognates sharing this morpheme.
    pub cognates: &'static [&'static str],
}

